CREATE TABLE IF NOT EXISTS business_applications(id text PRIMARY KEY,vendor_id text NOT NULL,organization text NOT NULL,title text NOT NULL,city text NOT NULL,category text NOT NULL,status text NOT NULL DEFAULT 'PENDING',reason text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS business_offers(id text PRIMARY KEY,vendor_id text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',city text NOT NULL,category text NOT NULL,price_cents bigint NOT NULL DEFAULT 0 CHECK(price_cents BETWEEN 0 AND 100000000),capacity int NOT NULL DEFAULT 0 CHECK(capacity BETWEEN 0 AND 100000),available int NOT NULL DEFAULT 0 CHECK(available>=0),status text NOT NULL DEFAULT 'DRAFT');
CREATE TABLE IF NOT EXISTS business_cart(customer_id text NOT NULL,offer_id text NOT NULL REFERENCES business_offers(id),quantity int NOT NULL CHECK(quantity BETWEEN 1 AND 20),PRIMARY KEY(customer_id,offer_id));
CREATE TABLE IF NOT EXISTS business_orders(id text PRIMARY KEY,customer_id text NOT NULL,status text NOT NULL,total_cents bigint NOT NULL,commission_cents bigint NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_id,idempotency_key));
CREATE TABLE IF NOT EXISTS business_items(order_id text NOT NULL REFERENCES business_orders(id),offer_id text NOT NULL REFERENCES business_offers(id),vendor_id text NOT NULL,title text NOT NULL,quantity int NOT NULL,price_cents bigint NOT NULL,total_cents bigint NOT NULL,commission_cents bigint NOT NULL,PRIMARY KEY(order_id,offer_id));
CREATE TABLE IF NOT EXISTS business_tickets(code text PRIMARY KEY,order_id text NOT NULL REFERENCES business_orders(id),offer_id text NOT NULL,vendor_id text NOT NULL,status text NOT NULL DEFAULT 'VALID');
CREATE TABLE IF NOT EXISTS business_outbox(event_id text PRIMARY KEY,payload jsonb NOT NULL,headers jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
